/**
 * DEMO catalog expansion — tech categories. Real product names/brands with published-looking specs.
 * Prices are illustrative reference prices (USD); every offer is seeded with source = "demo".
 *
 * Entry DSL: [brand, model, priceUsd, "Attr=Value|Attr=Value", variants?]
 *  - model may contain "{v}" where the variant label is inserted (otherwise it is appended after a comma).
 *  - variants: [label, priceDeltaUsd, "Attr=Value overrides"] → each becomes its own product, linked as siblings.
 */

export type Variant = [label: string, deltaUsd: number, specs: string];
export type Entry = [brand: string, model: string, priceUsd: number, specs: string, variants?: Variant[]];

const st = (...list: [string, number][]): Variant[] => list.map(([s, d]) => [s, d, `Storage=${s}`]);
const ramSt = (...list: [string, string, number][]): Variant[] => list.map(([r, s, d]) => [`${r} RAM, ${s}`, d, `RAM=${r}|Storage=${s}`]);
const sizes = (...list: [string, number][]): Variant[] => list.map(([s, d]) => [`${s}"`, d, `Screen size=${s} in`]);

